contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address a1, address a2, uint256 k) public payable {
        require(true);
        // decide which address to use repeatedly, from inputs
        address a = (k % 2 == 0) ? a1 : a2;
        bool r1 = c.setOwner(a); if (__ESBMC_reverted()) return;
        bool r2 = c.setOwner(a); if (__ESBMC_reverted()) return;
        bool r3 = c.setOwner(a == a1 ? a2 : a1); if (__ESBMC_reverted()) return; // a different call in between
        bool r4 = c.setOwner(a); if (__ESBMC_reverted()) return;
        address finalOwner = c.owner(); if (__ESBMC_reverted()) return;
        assert(r1 && r2 && r4 && !r3 == false && finalOwner == a && r3 == true && c.owner() == a);
    }
    receive() external payable {}
}

