pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address a1, address a2, uint256 k) internal {
        vm.assume(true);
        address a = (k % 2 == 0) ? a1 : a2;
        bool r1;
        try c.setOwner(a) returns (bool __r) { r1 = __r; } catch { return; }
        bool r2;
        try c.setOwner(a) returns (bool __r) { r2 = __r; } catch { return; }
        bool r3;
        try c.setOwner(a == a1 ? a2 : a1) returns (bool __r) { r3 = __r; } catch { return; }
        bool r4;
        try c.setOwner(a) returns (bool __r) { r4 = __r; } catch { return; }
        address finalOwner;
        try c.owner() returns (address __r) { finalOwner = __r; } catch { return; }
        assertTrue(r1 && r2 && r4 && !r3 == false && finalOwner == a && r3 == true && c.owner() == a);
    }

    function testFuzz_run(address a1, address a2, uint256 k) public {
        vm.assume(a1.code.length == 0 && uint160(a1) > 0xffff && a1 != address(this) && a1 != address(c) && a1 != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && a1 != 0x000000000000000000636F6e736F6c652e6c6f67 && a1 != 0x4e59b44847b379578588920cA78FbF26c0B4956C && a1 != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(a2.code.length == 0 && uint160(a2) > 0xffff && a2 != address(this) && a2 != address(c) && a2 != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && a2 != 0x000000000000000000636F6e736F6c652e6c6f67 && a2 != 0x4e59b44847b379578588920cA78FbF26c0B4956C && a2 != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(a1, a2, k);
    }

    receive() external payable {}
}
